<?php require dirname(__DIR__,2).'/app/admin_view.php';admin_header('news','News & Updates'); ?>
<section class="card"><h2>News publishing</h2><button class="btn" id="new-post">New article</button><div id="posts"></div><form id="news-editor" class="card"><input type="hidden" name="id"><label>Title<input class="input" name="title" maxlength="200" required></label><label>Category<input class="input" name="category" maxlength="80"></label><label>Article<textarea class="input" name="body" rows="16" required></textarea></label><label>Cover image<input id="cover" class="input" type="file" accept="image/jpeg,image/png,image/webp"></label><input type="hidden" name="cover_url"><label>Visibility<select class="input" name="status"><option value="draft">Draft</option><option value="published">Published</option></select></label><button class="btn primary">Save article</button><p id="news-status" role="status"></p></form><a href="/news">Open public news</a></section>
<script src="/assets/rich-editor.js"></script><script>const newsRich=tdcRichEditor(document.querySelector('#news-editor textarea'));let csrf='',posts=[];const form=document.getElementById('news-editor'),statusEl=document.getElementById('news-status');async function loadNews(){const r=await fetch('/api/news.php?admin=1'),d=await r.json();if(!r.ok){statusEl.textContent=d.error;return}csrf=d.csrf;posts=d.posts;const root=document.getElementById('posts');root.replaceChildren();for(const p of posts){const button=document.createElement('button');button.className='btn';button.textContent=p.title+' · '+p.status;button.onclick=()=>{form.reset();for(const key of ['id','title','category','body','cover_url','status'])form.elements[key].value=p[key]||''};root.append(button)}}document.getElementById('new-post').onclick=()=>{form.reset();form.elements.id.value='';form.elements.cover_url.value=''};form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const image=document.getElementById('cover').files[0];if(image){const body=new FormData();body.append('image',image);const r=await fetch('/api/admin-upload.php',{method:'POST',headers:{'X-CSRF-Token':csrf},body}),d=await r.json();if(!r.ok)throw Error(d.error);form.elements.cover_url.value=d.url}const r=await fetch('/api/news.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(Object.fromEntries(new FormData(form)))}),d=await r.json();if(!r.ok)throw Error(d.error);form.elements.id.value=d.id;statusEl.textContent='Article saved';await loadNews()}catch(e){statusEl.textContent=e.message}finally{button.disabled=false}};loadNews();</script><?php admin_footer(); ?>
